  function tdRows(){const source=state.tdScenario==='empty'?[]:state.tdScenario==='foreign'?tdFixtures:dRows().filter(r=>r.tag===(state.dTag||'日常'));return source.filter(r=>state.tdPeriod==='all'||((r.year||2026)===state.year&&(state.tdPeriod==='year'||(r.month||state.month)===state.month)));}
  function tdSummary(){const rows=tdRows(),expense=rows.filter(r=>!r.excludeStats&&(r.type||'expense')==='expense').reduce((s,r)=>s+(r.nativeAmount??r.amount),0),income=rows.filter(r=>!r.excludeStats&&r.type==='income').reduce((s,r)=>s+(r.nativeAmount??r.amount),0),name=state.tdScenario==='foreign'?'旅行':state.dTag||'日常',categories=[...new Set(rows.map(r=>r.subcategory||r.category))],groups=new Map();for(const r of rows){if(r.excludeStats||(r.type||'expense')!=='expense')continue;const name=r.subcategory||r.category,g=groups.get(name)||{name,icon:pIcon(r.category),amount:0,count:0,parent:r.category};g.amount+=r.nativeAmount??r.amount;g.count++;groups.set(name,g);}return {rows,expense,income,name,categories,groups:[...groups.values()].sort((a,b)=>b.amount-a.amount)};}
  function tdBody(){const d=tdSummary();return `<div class="bc-subhead"><div class="bc-heading-left">${btn('back',icon('chevron-left'),'返回')}<h2>标签详情</h2></div><div class="td-actions">${btn('td-edit',icon('pencil-line'),'编辑标签')}${btn('td-delete',icon('trash-2'),'删除标签')}</div></div><div class="td-scope bc-segment">${[['month','月'],['year','年'],['all','全部']].map(([k,n])=>btn('td-period:'+k,n,n,'',`aria-pressed="${state.tdPeriod===k}"`)).join('')}</div>${state.tdPeriod==='all'?'':btn('td-date',`${icon('calendar-days')}${state.year}${state.tdPeriod==='month'?'-'+String(state.month).padStart(2,'0'):''}`,'选择周期','td-date')}${surface(`<div class="d-identity"><span class="bc-entry-icon warm" style="color:${({green:'#629b65',teal:'#219c9c',amber:'#a88b17',purple:'#8174c7',pink:'#c56f99',blue:'#5795c8'})[tagColors[d.name]]||'#219c9c'}">${icon('tag')}</span><div><h3>${tag(d.name)}</h3><small>${state.tdScope==='all'?'全部账本':esc(state.ledger)}</small></div></div><div class="d-label">总支出</div><div class="d-amount bc-num"><span>¥</span>${shown(d.expense)}</div><div class="d-hero-stats">${dMetric('总收入','¥'+shown(d.income))}${dMetric('关联分类',d.categories.length)}${dMetric('交易笔数',d.rows.length+'笔')}</div>`,'d-hero',true)}${state.tdScope==='all'?'<p class="bc-small">按原账本金额汇总</p>':''}${d.groups.length?surface(`<h3>分类分布</h3><div class="d-distribution">${d.groups.map(g=>btn('td-category:'+g.name,`<span class="bc-entry-icon">${jCategoryVisual(g.name,g.icon)}</span><span class="d-child-copy"><span><span>${esc(g.name)}</span><span>${shown(g.amount)}</span></span><small>${g.count}笔</small><div class="d-child-track"><i style="width:${d.expense?g.amount/d.expense*100:0}%"></i></div></span>${icon('chevron-right')}`,'查看分类 '+g.name,'')).join('')}</div>`):''}${surface(`<div class="bc-between"><h3>关联交易</h3><span class="bc-small">${d.rows.length}笔</span></div>${d.rows.map(r=>`<div class="td-day">${r.year||2026}-${String(r.month||state.month).padStart(2,'0')}-${String(r.day).padStart(2,'0')}</div>${cLegacyTagTransaction(r,d.name)}`).join('')||'<div class="d-empty"><b>暂无关联交易</b><p>使用此标签的交易将在此显示</p></div>'}`,'c3-consumer-list')}${btn('td-record',`${icon('plus')}使用此标签记一笔`,'使用此标签记一笔','bc-primary')}`;}
  dTagDetail=tdBody;
  const tdRoutes=[['tag-foreign-detail','标签详情 · 原币与多状态','foreign','current'],['tag-all-ledgers-detail','标签详情 · 全部账本','foreign','all'],['tag-empty-detail','标签详情 · 空记录','empty','current']];
  let tdPreviewGroup=[...picker.querySelectorAll('optgroup')].find(g=>g.label==='补齐 · 标签与分类');if(!tdPreviewGroup){tdPreviewGroup=document.createElement('optgroup');tdPreviewGroup.label='补齐 · 标签与分类';picker.appendChild(tdPreviewGroup);}
  for(const [key,title] of tdRoutes){fDefine(key,title,'标签与分类','tag/tag_detail_page.dart',tdBody);tdPreviewGroup.appendChild(new Option(title,'flow-'+key));}
  const tdPreviousPrepare=rPrepareRoute;rPrepareRoute=function(){const hit=tdRoutes.find(([key])=>state.page==='flow-'+key);if(hit){state.tdScenario=hit[2];state.tdScope=hit[3];state.tdPeriod='all';if(hit[2]==='foreign'){const foreign=tdFixtures.find(r=>r.currency&&r.currency!==state.fBaseCurrency&&r.tag);if(foreign)state.dTag=foreign.tag;}state.page='tagDetail';}tdPreviousPrepare();};
  rSpecs['td-period-picker']={title:'选择周期',host:'tagDetail',kind:'sheet'};
  const tdPreviousModal=rModalBody;rModalBody=function(key){if(key!=='td-period-picker')return tdPreviousModal(key);const d=jDraft('month');return `${jWheelGroup(jWheel('year',jYears.filter(y=>y<=2026),d.year,'年','年份')+(state.tdPeriod==='year'?'':jWheel('month',jRange(12,1),d.month,'月','月份')))}<div class="bc-inline-actions">${btn('r-close','取消','取消选择周期','bc-secondary')}${btn('td-period-confirm','确认','确认周期','bc-primary')}</div>`;};
  root.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;const [action,arg]=el.dataset.action.split(':');if(action==='d-tag'){state.tdScenario='';state.tdScope='current';state.tdPeriod='all';return;}if(!action.startsWith('td-'))return;event.preventDefault();event.stopImmediatePropagation();if(action==='td-period'){state.tdPeriod=arg;render();}else if(action==='td-date'){state.jWheel=null;rOpenModal('td-period-picker');}else if(action==='td-period-confirm'){for(const w of phone.querySelectorAll('[data-j-wheel]'))jWheelRead(w);state.year=state.jWheel.year;state.month=state.jWheel.month;rDismiss();render();}else if(action==='td-delete')sheet('删除标签',`<p>删除「${esc(tdSummary().name)}」及关联关系，账单保留。</p><div class="bc-inline-actions">${btn('close','取消','取消删除标签','bc-secondary')}${btn('td-delete-confirm','删除','确定删除标签','bc-primary')}</div>`);else if(action==='td-delete-confirm'){state.tdScenario='empty';closeSheet();render();notice('标签已删除，账单保留');}else if(action==='td-edit')navigate('leaf:编辑标签:'+tdSummary().name);else if(action==='td-category'){const row=tdRows().find(r=>(r.subcategory||r.category)===arg);if(row)dOpenCategory(dParentOf(row),row.subcategory||'',row.type==='income'?'income':'expense');}else if(action==='td-record'){state.tag=tdSummary().name;state.recordType='expense';state.expression='0';state.amount='0';state.note='';navigate('editor');}else if(action==='td-row'){const row=tdRows().find(r=>String(r.id)===arg);if(row){state.recordType=row.type||'expense';state.note=row.title;state.amount=String(row.amount);state.expression=state.amount;state.category=row.category;state.tag=tdSummary().name;state.fRecordCurrency=row.currency||'CNY';navigate('editor');}}},true);
